 function dialog(heading,body,house=false){const d=$('#town-dialog');d.classList.remove('is-collections','is-province-case');d.classList.toggle('is-house',house===true);d.classList.toggle('is-building',house==='building');$('#town-dialog-title').textContent=heading;$('#town-dialog-body').innerHTML=body+'<p class="town-dialog-error" id="town-dialog-error" role="alert"></p>';if(!d.open)d.showModal();}
 function closeDialog(){const d=$('#town-dialog');d.close();if(location.hash.includes('/house/'))history.replaceState(null,'','#'+S.province);}
