 $('#town-dialog').addEventListener('cancel',()=>{if(location.hash.includes('/house/'))history.replaceState(null,'','#'+S.province);});
 async function refreshSelf(){const id=user()?.id;if(!id){S.me=null;S.pet=null;return;}const [me,pet]=await Promise.all([N.call('state'),N.rpc('foamlab_pet')]);if(user()?.id!==id)return;S.me=me;S.pet=pet;S.options=me.options||S.options||{};S.muted=matchMedia('(prefers-reduced-motion: reduce)').matches||pet.pet.motion===false;window.dispatchEvent(new CustomEvent('foamlab:activity'));}
 function needResident(){if(!user()){dialog('登录后入住','<p>用网站现有的 GitHub 账号登录，就能带着自己的熊猫来到街道。</p><a class="town-link" href="/account/?next=%2Ftown%2F">使用 GitHub 登录 →</a>');return false;}if(!S.me?.resident){join();return false;}return true;}
