 let neighborTimer=null,neighborRevision=0,neighborRefresh=null;
 function stopNeighborStatus(){clearTimeout(neighborTimer);neighborRevision++;neighborRefresh=null;}
 function watchNeighbors(){
  stopNeighborStatus();const rev=neighborRevision,owner=user()?.id,list=$('.town-neighbor-list');if(!list)return;
  const badges=[...list.querySelectorAll('[data-neighbor-status]')],ids=badges.map(n=>n.dataset.neighborStatus);let busy=false;
  const paint=(n,state,label)=>{n.dataset.state=state;n.textContent=label;};
  if(!owner){badges.forEach(n=>paint(n,'unknown','登录后可见'));return;}
  const valid=()=>rev===neighborRevision&&list.isConnected&&$('#town-dialog').open&&user()?.id===owner;
  neighborRefresh=async()=>{
   clearTimeout(neighborTimer);if(busy||!valid()||document.hidden||!ids.length)return;busy=true;
   try{const data=await N.rpc('foamlab_town_presence_status',{user_ids:ids});if(!valid())return;
    const states=new Map((data?.states||[]).map(r=>[r.user_id,r.online]));
    badges.forEach(n=>{const online=states.get(n.dataset.neighborStatus);paint(n,online===true?'online':online===false?'offline':'unknown',online===true?'在线':online===false?'离线':'状态未知');});
   }catch{if(valid())badges.forEach(n=>paint(n,'unknown','暂时无法更新'));}
   finally{busy=false;if(valid()&&!document.hidden)neighborTimer=setTimeout(()=>neighborRefresh?.(),30000);}
  };
  void neighborRefresh();
 }
