 function directory(){dialog('小镇建筑',`<div class="town-building-directory">${S.buildings.filter(b=>!b[3]).map(b=>button(`<span class="town-building-icon" aria-hidden="true">${b[0]==='spot'?(window.FoamProvinceArt.has(S.province)?window.FoamProvinceArt.medal(S.province):A.spot(S.street.spot)):b[1]==='去其他小镇'?window.FoamTownIcon('map'):A.building(b[0])}</span><span>${E(b[1])}</span><span class="town-building-arrow" aria-hidden="true">→</span>`,'building-open',`data-index="${S.buildings.indexOf(b)}"`)).join('')}</div>${S.street.questions?.length?'<h3>邻居正在讨论</h3><ul>'+S.street.questions.map(q=>`<li><a href="/community/?topic=${q.id}">${E(q.title)}</a></li>`).join('')+'</ul>':''}<p class="town-note">点击建筑，查看介绍与学习入口。</p>${button('文字版街道','text')}`);}
 function quickbar(){return (S.pet?.pet?.quickbar||['wave','highfive','smile','heart','thumb','give-bamboo']).map((id,n)=>button(`<kbd>${n+1}</kbd><i aria-hidden="true">${window.FoamTownGlyph?.(id)||E(icons[id]||'✦')}</i><span>${E(title(id))}</span>`,'action',`class="town-action-button" data-id="${E(id)}" aria-label="${E(title(id))}（快捷键 ${n+1}）"`)).join('');}
 const personalStates=[['stroll','闲逛','#8ba86f'],['study','学习','#78a9b4'],['music','听歌','#af91bd'],['nap','打盹','#b3a071'],['busy','忙碌','#bf8871'],['away','暂离','#8b9690']];
