 function renderResidents(){const layer=$('#town-residents');if(!layer||!S.street)return;const cards=[...(S.me?.resident?S.street.online:S.street.residents)];if(S.me?.card){const mine=cards.findIndex(r=>r.user_id===user()?.id);if(mine>=0)cards[mine]=S.me.card;else cards.unshift(S.me.card);}const limit=navigator.hardwareConcurrency<=4||innerWidth<600?15:Math.min(30,S.options?.max_online||30);S.cards=cards.slice(0,limit);const signature=JSON.stringify(S.cards);if(layer.dataset.cards===signature)return;layer.dataset.cards=signature;layer.innerHTML=S.cards.map((c,i)=>{const mine=c.user_id===user()?.id;const x=mine?S.x??140:S.me?.resident?100+hashCode(c.user_id)%(Math.min(S.worldWidth-180,3000)):70+(S.buildings.findIndex(b=>b[3]?.user_id===c.user_id))*238+65;return `<button type="button" class="town-resident ${mine?'is-me':''}" data-town="resident" data-user="${c.user_id}" data-form="${E(c.form)}" data-outfit="${E(c.outfit)}" data-ride="${E(c.ride)}" data-decoration="${E(c.decoration||'no-decor')}" style="--x:${x}px" aria-label="${E(c.name)}，等级 ${c.level}，查看住处与互动"><i class="town-shadow" aria-hidden="true"></i><i class="town-body" aria-hidden="true"><i class="town-pixel-panda"${(L=>L?` style="background-image:${L}"`:"")(window.FoamTownLook?.(c).background)}></i>${window.foamPandaArt()}</i><span>${E(c.name)} · Lv.${c.level}</span>${c.question?'<b class="town-question" aria-label="有待解决的问题">?</b>':''}</button>`;}).join('');S.game?.renderResidents();}
