 let onlineTimer;function queueOnline(){void neighborRefresh?.();clearTimeout(onlineTimer);onlineTimer=setTimeout(async()=>{if(!S.province)return;try{const province=S.province;const data=await N.rpc('foamlab_town_street',{province,page:S.page,query:S.query});if(province!==S.province)return;S.street.online=data.online||[];renderResidents();connection('online');}catch{connection('offline');}},600);}
