 window.FoamTownEggContext={get:()=>({name:provinceName(S.province),province:S.province,form:S.pet?.pet?.form,outfit:S.pet?.pet?.outfit,decoration:S.pet?.pet?.decoration,home:S.me?.resident?.province,self:S.me?.card,status:personalStatus()[1],connected:S.online,online:S.street?.online||[]}),home:async page=>{if(!S.me?.resident)return;closeDialog();await N.disconnect();S.province=S.me.resident.province;S.page=page;S.query='';S.route++;history.replaceState(null,'','#'+S.province);await street();N.connect(S.province,{event:onEvent,sync:queueOnline,status:connection});const i=S.buildings.findIndex(b=>b[3]?.user_id===user()?.id),d=S.game?.door(i);if(d){S.game.stopMovement();Object.assign(S.game.position,d);Object.assign(S.game.me,d);S.game.camera.ready=false;}}};
 // Start every independent request at once: static data, the map, your own state and (when we can guess it) your street.
 // Decode the main atlases while the data loads, so the street appears with its buildings already drawn.
 const pictures=()=>Promise.race([Promise.all(['terrain','buildings','homes','scenery'].map(n=>{const img=new Image();img.src='/assets/town/'+n+'-atlas.webp';return img.decode().catch(()=>{});})),new Promise(r=>setTimeout(r,2500))]);
 let initialization=0,initialIdentity;
 async function init(){const version=++initialization;try{root.removeAttribute('data-ready');root.setAttribute('aria-busy','true');loading(12,'正在唤醒熊猫…');const art=pictures();const statics=Promise.all(['/assets/town/provinces.json','/assets/town/catalog.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('小镇资料暂时无法读取，请刷新重试。');return r.json();}));
  await window.foamAuth?.ready;if(version!==initialization)return;initialIdentity=user()?.id||null;loading(35,'正在打开小镇大门…');
  const hash=decodeURIComponent(location.hash.slice(1)).split('/')[0];let guess=hash&&hash!=='map'?hash:null;if(!hash&&user()){try{guess=localStorage.getItem(lastKey());}catch{}}
  const mapRequest=N.rpc('foamlab_town_map'),selfRequest=user()?refreshSelf().catch(error=>setStatus(error.message,true)):null;
  if(guess&&/^[a-z]+$/.test(guess))S.prefetch={province:guess,promise:N.rpc('foamlab_town_street',{province:guess,page:0,query:''}).catch(()=>null)};
  [S.provinces,S.catalog]=await statics;const enabled=await mapRequest;if(version!==initialization)return;if(!enabled.enabled){disabled();return;}S.mapStats=enabled;S.mapStatsAt=Date.now();loading(62,'正在铺设街道…');
  await selfRequest;if(version!==initialization)return;if(S.prefetch&&S.me?.resident&&!hash&&S.prefetch.province!==S.me.resident.province)S.prefetch=null;loading(84,'熊猫正在出门…');await art;if(version!==initialization)return;await route();if(version!==initialization)return;loading(100,'到啦！');root.setAttribute('aria-busy','false');root.dataset.ready='true';}catch(error){if(version!==initialization)return;setStatus(error.message,true);root.setAttribute('aria-busy','false');root.dataset.ready='error';$('#town-content').innerHTML=button('重新连接','retry');root.querySelector('[data-town=retry]').onclick=init;}}
